63	// registerInstance is one instance in the final service list.
64	type registerInstance struct {
65		ID       string `json:"id"`
66		Address  string `json:"address"`
67		Health   string `json:"health"`
68		Sequence int64  `json:"sequence"`
69		Reason   string `json:"reason,omitempty"`
70	}
71	
72	// registerService is one service in the final service list.
73	type registerService struct {
74		Service   string             `json:"service"`
75		Revision  int                `json:"revision"`
76		Instances []registerInstance `json:"instances"`
77	}
78	
79	// registerResult is the per-item outcome.
80	type registerResult struct {
81		Service          string `json:"service"`
82		OK               bool   `json:"ok"`
83		Changed          bool   `json:"changed,omitempty"`
84		Revision         int    `json:"revision"`
85		Error            string `json:"error,omitempty"`
86		Reason           string `json:"reason,omitempty"`
87		ExpectedRevision int    `json:"expectedRevision,omitempty"`
88		ActualRevision   int    `json:"actualRevision,omitempty"`
89		Sequence         int64  `json:"sequence,omitempty"`
90		InstanceID       string `json:"instanceId,omitempty"`
91		Address          string `json:"address,omitempty"`
92	}
93	
94	// registerOutput is the full register output.
95	type registerOutput struct {
96		Results  []registerResult  `json:"results"`
97		Services []registerService `json:"services"`
98	}
99	
100	// runRegister processes registration requests from the process standard
101	// streams. It returns the process exit code: 0 when all registrations succeed
102	// and the result is fully written, 1 otherwise.
103	func runRegister() int {
104		return runRegisterIO(os.Stdin, os.Stdout, os.Stderr)
105	}
106	
107	// runRegisterIO is runRegister with injectable streams. in supplies the JSON
108	// request batch, out receives the single JSON result document and errOut
109	// receives diagnostics (in particular a result-delivery failure, which must
110	// never be mixed into out).
111	func runRegisterIO(in io.Reader, out io.Writer, errOut io.Writer) int {
112		data, err := io.ReadAll(in)
113		if err != nil {
114			return failRegister(out, errOut, fmt.Sprintf("could not read standard input: %v", err))
115		}
116	
117		var top struct {
118			Requests json.RawMessage `json:"requests"`
119		}
120		if err := json.Unmarshal(data, &top); err != nil {
121			return failRegister(out, errOut, fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
122		}
123		if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
124			return failRegister(out, errOut, "input must contain a \"requests\" array")
125		}
126		var rawRequests []json.RawMessage
127		if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
128			return failRegister(out, errOut, "\"requests\" must be a JSON array")
129		}
130	
131		proc := &registerProcessor{
132			registry: indexroom.NewRegistry(),
133			results:  make([]registerResult, 0, len(rawRequests)),
134		}
135	
136		for _, raw := range rawRequests {
137			var head struct {
138				Service string          `json:"service"`
139				Type    json.RawMessage `json:"type"`
140			}
141			_ = json.Unmarshal(raw, &head)
142			service := strings.TrimSpace(head.Service)
143	
144			reqType := "register"
145			if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
146				var t string
147				if err := json.Unmarshal(head.Type, &t); err != nil {
148					proc.invalid(service, "type must be a string")
149					continue
150				}
151				reqType = t
152			}
153	
154			switch reqType {
155			case "", "register":
156				proc.registerRequest(raw, service)
157			case "health":
158				proc.healthRequest(raw, service)
159			case "select":
160				proc.selectRequest(raw, service)
161			default:
162				proc.invalidf(service, "unknown type %q", reqType)
163			}
164		}
165	
166		results, anyFailed := proc.results, proc.failed
167		registry := proc.registry
168	
169		services := make([]registerService, 0)
170		for _, view := range registry.Snapshot() {
171			insts := make([]registerInstance, 0, len(view.Instances))
172			for _, inst := range view.Instances {
173				insts = append(insts, registerInstance{
174					ID:       inst.ID,
175					Address:  inst.Address,
176					Health:   string(inst.Health),
177					Sequence: inst.Sequence,
178					Reason:   inst.Reason,
179				})
180			}
181			services = append(services, registerService{
182				Service:   view.Service,
183				Revision:  view.Revision,
184				Instances: insts,
185			})
186		}
187	
188		if err := writeRegisterOutput(out, registerOutput{Results: results, Services: services}); err != nil {
189			// The request results could not be delivered. This is independent of
190			// whether the requests themselves succeeded: the caller must be able to
191			// tell an undelivered result from a rejected request.
192			reportRegisterDeliveryFailure(errOut, err)
193			return 1
194		}
195		if anyFailed {
196			return 1
197		}
198		return 0
199	}
200	
201	// registerProcessor runs the request batch in input order. Failed items keep
202	// their slot in results and set failed; later items still run against the
203	// state committed by earlier successful items.
204	type registerProcessor struct {
205		registry *indexroom.Registry
206		results  []registerResult
207		failed   bool
208	}
209	
210	// invalid records an input-validation failure for an item. Content validity is
211	// checked before any business rule, so the revision stamped here is the
212	// service's current revision when the item is handled.
213	func (p *registerProcessor) invalid(service, reason string) {
214		p.failed = true
215		p.results = append(p.results, registerResult{
216			Service:  service,
217			OK:       false,
218			Error:    "invalid",
219			Reason:   reason,
220			Revision: p.registry.RevisionOf(service),
221		})
222	}
223	
224	// invalidf is invalid with a formatted reason.
225	func (p *registerProcessor) invalidf(service, format string, args ...any) {
226		p.invalid(service, fmt.Sprintf(format, args...))
227	}
228	
229	// reject records a business-rule failure (conflict, not_found, stale or
230	// no_healthy), keeping each operation's distinct result fields. Health
231	// rejections additionally carry the current sequence; register and select
232	// pass 0 so it stays omitted.
233	func (p *registerProcessor) reject(service string, kind indexroom.OutcomeKind, reason string, revision, expected, actual int, sequence int64) {
234		p.failed = true
235		p.results = append(p.results, registerResult{
236			Service:          service,
237			OK:               false,
238			Error:            string(kind),
239			Reason:           reason,
240			Revision:         revision,
241			ExpectedRevision: expected,
242			ActualRevision:   actual,
243			Sequence:         sequence,
244		})
245	}
246	
247	// succeed records an accepted item; omitempty keeps zero-valued fields out of
248	// the output exactly as before the refactor.
249	func (p *registerProcessor) succeed(result registerResult) {
250		result.OK = true
251		p.results = append(p.results, result)
252	}
253	
254	// registerRequest processes one register request, appending its outcome.
255	func (p *registerProcessor) registerRequest(raw json.RawMessage, service string) {
256		var req struct {
257			Service   string          `json:"service"`
258			Revision  *int64          `json:"expectedRevision"`
259			Instances json.RawMessage `json:"instances"`
260		}
261		if err := json.Unmarshal(raw, &req); err != nil {
262			p.invalidf(service, "request must be an object with service, expectedRevision and instances: %v", err)
263			return
264		}
265		service = strings.TrimSpace(req.Service)
266	
267		if req.Revision == nil {
268			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
269			return
270		}
271		if !isJSONArray(req.Instances) {
272			p.invalid(service, "instances must be an array")
273			return
274		}
275		var instances []indexroom.Instance
276		if err := json.Unmarshal(req.Instances, &instances); err != nil {
277			p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
278			return
279		}
280	
281		registration, err := p.registry.ValidateRegistration(service, int(*req.Revision), instances)
282		if err != nil {
283			p.invalid(service, err.Error())
284			return
285		}
286	
287		outcome := p.registry.Apply(registration)
288		if !outcome.OK {
289			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
290			return
291		}
292		p.succeed(registerResult{
293			Service:  outcome.Service,
294			Changed:  outcome.Changed,
295			Revision: outcome.Revision,
296		})
297	}
298	
299	// healthRequest processes one health observation request, appending its outcome.
300	func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
301		var req struct {
302			Service    string  `json:"service"`
303			InstanceID string  `json:"instanceId"`
304			Revision   *int64  `json:"expectedRevision"`
305			Sequence   *int64  `json:"sequence"`
306			Healthy    *bool   `json:"healthy"`
307			Reason     *string `json:"reason"`
308		}
309		if err := json.Unmarshal(raw, &req); err != nil {
310			p.invalidf(service, "health request must be an object with service, instanceId, expectedRevision, sequence and healthy: %v", err)
311			return
312		}
313		service = strings.TrimSpace(req.Service)
314	
315		if req.Revision == nil {
316			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
317			return
318		}
319		if req.Sequence == nil {
320			p.invalid(service, "sequence is required and must be a positive integer")
321			return
322		}
323		if req.Healthy == nil {
324			p.invalid(service, "healthy is required and must be a boolean")
325			return
326		}
327		reason := ""
328		if req.Reason != nil {
329			reason = *req.Reason
330		}
331	
332		update, err := p.registry.ValidateHealth(service, req.InstanceID, int(*req.Revision), *req.Sequence, *req.Healthy, reason)
333		if err != nil {
334			p.invalid(service, err.Error())
335			return
336		}
337	
338		outcome := p.registry.ApplyHealth(update)
339		if !outcome.OK {
340			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, outcome.Sequence)
341			return
342		}
343		p.succeed(registerResult{
344			Service:  outcome.Service,
345			Changed:  outcome.Changed,
346			Revision: outcome.Revision,
347			Sequence: outcome.Sequence,
348		})
349	}
350	
351	// selectRequest processes one select request, appending its outcome.
352	// A selection performs no network access and never alters registrations or
353	// health records; it only advances the service's healthy-instance rotation
354	// and, for requests carrying a sessionKey, maintains that session's binding.
355	func (p *registerProcessor) selectRequest(raw json.RawMessage, service string) {
356		var req struct {
357			Service  string          `json:"service"`
358			Revision *int64          `json:"expectedRevision"`
359			Session  json.RawMessage `json:"sessionKey"`
360		}
361		if err := json.Unmarshal(raw, &req); err != nil {
362			p.invalidf(service, "select request must be an object with service and expectedRevision: %v", err)
363			return
364		}
365		service = strings.TrimSpace(req.Service)
366	
367		if req.Revision == nil {
368			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
369			return
370		}
371	
372		// sessionKey is optional: absent means an ordinary rotating selection. An
373		// explicitly provided null, a non-string value or a blank string is
374		// invalid; the registry trims the key and treats keys equal after trimming
375		// as the same session.
376		var sessionKey *string
377		if len(req.Session) > 0 {
378			if strings.TrimSpace(string(req.Session)) == "null" {
379				p.invalid(service, "sessionKey must be a string, not null")
380				return
381			}
382			var key string
383			if err := json.Unmarshal(req.Session, &key); err != nil {
384				p.invalid(service, "sessionKey must be a string")
385				return
386			}
387			sessionKey = &key
388		}
389	
390		selection, err := p.registry.ValidateSelectionWithSession(service, int(*req.Revision), sessionKey)
391		if err != nil {
392			p.invalid(service, err.Error())
393			return
394		}
395	
396		outcome := p.registry.Select(selection)
397		if !outcome.OK {
398			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
399			return
400		}
401		p.succeed(registerResult{
402			Service:    outcome.Service,
403			Revision:   outcome.Revision,
404			InstanceID: outcome.InstanceID,
405			Address:    outcome.Address,
406			Sequence:   outcome.Sequence,
407		})
408	}
409	
410	// failRegister emits a top-level input error as the single JSON document on
411	// out and returns exit code 1. If that error JSON itself cannot be written,
412	// the delivery failure is diagnosed on errOut (out may already hold a partial
413	// document, so no second JSON is appended) and the exit code stays 1.
414	func failRegister(out io.Writer, errOut io.Writer, reason string) int {
415		if err := writeRegisterOutput(out, struct {
416			Error string `json:"error"`
417		}{Error: reason}); err != nil {
418			reportRegisterDeliveryFailure(errOut, err)
419		}
420		return 1
421	}
422	
423	// reportRegisterDeliveryFailure reports on errOut that the register command's
424	// JSON result could not be delivered, preserving the underlying write error.
425	// It never writes to standard output, which may already contain a partial
426	// result.
427	func reportRegisterDeliveryFailure(errOut io.Writer, err error) {
428		fmt.Fprintf(errOut, "register: failed to write request results to standard output: %v\n", err)
429	}
430	
431	// writeRegisterOutput writes v as the single indented JSON document on w.
432	// Standard output is dedicated to this document, so a write failure is returned
433	// instead of swallowed: the caller must not attempt to append another document
434	// after a partial write.
435	func writeRegisterOutput(w io.Writer, v any) error {
436		enc := json.NewEncoder(w)
437		enc.SetIndent("", "  ")
438		return enc.Encode(v)
439	}
440	
441	// isJSONArray reports whether raw is a JSON array (ignoring leading whitespace).
442	func isJSONArray(raw json.RawMessage) bool {
443		for _, b := range raw {
444			switch b {
445			case ' ', '\t', '\n', '\r':
446				continue
447			case '[':
448				return true
449			default:
450				return false
451			}
452		}
453		return false
454	}
455	
456	func runDemo() {
457		index := indexroom.New()
458		blocks := []indexroom.Block{
459			{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1", "t2"}},
460			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t3"}},
461		}
462		for _, block := range blocks {
463			if err := index.Append(block); err != nil {
464				fmt.Printf("append refused at height %d: %v\n", block.Height, err)
465				continue
466			}
467			fmt.Printf("indexed height=%d txs=%d\n", block.Height, len(block.Txs))
468		}
469		if err := index.Append(indexroom.Block{Height: 3, Hash: "h3", Parent: "h1"}); err != nil {
470			fmt.Println("non-linear block refused:", err)
471		}
472		dropped, err := index.Reorg([]indexroom.Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"t4", "t5"}}})
473		fmt.Printf("reorg dropped=%v err=%v tip=%d\n", dropped, err, index.Tip)
474	}
